#!/usr/bin/env python3
"""
Open Source License Scanner (OSLS) — v24 Launcher
====================================================
A zero-install, self-contained launcher.

Usage
-----
  python OSLS_App.py            # starts on default port 8420
  python OSLS_App.py --port 9000
  python OSLS_App.py --no-browser   # start server without auto-opening browser

Requirements
------------
  Python 3.7+  (standard library only — no pip installs needed)

How it works
------------
  The HTML app is embedded directly inside this .py file as a base64-encoded
  string.  At start-up the launcher:
    1. Decodes the HTML back to UTF-8.
    2. Spins up a tiny http.server on localhost.
    3. Serves the HTML from memory (no temp files written to disk).
    4. Opens your default browser automatically.

  All license lookups (npm, PyPI, Hugging Face, GitHub, ScanCode) are made
  directly from the browser to the respective public APIs — this Python process
  is only a file-server and does NOT proxy any network traffic.
"""

