# ── HTTP Handler ──────────────────────────────────────────────────────────────
class OSLSHandler(BaseHTTPRequestHandler):
    """Minimal HTTP handler — serves the embedded HTML for any GET request,
    returns 404 for anything else."""

    _html_bytes: bytes = None   # class-level cache; set once at start-up

    def log_message(self, fmt, *args):
        """Suppress the default per-request console noise; keep it clean."""
        pass   # comment this out if you want verbose access logs

    def do_GET(self):
        path = urlparse(self.path).path.rstrip("/") or "/"

        if path in ("/", "/index.html"):
            self._serve_html()
        elif path == "/health":
            self._send_json(200, b'{"status":"ok"}')
        else:
            self._send_text(404, b"Not found")

    def do_HEAD(self):
        path = urlparse(self.path).path.rstrip("/") or "/"
        if path in ("/", "/index.html"):
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(self._html_bytes)))
            self.end_headers()
        else:
            self._send_text(404, b"")

    # ── OPTIONS (CORS pre-flight — keeps browser fetch() calls happy) ──
    def do_OPTIONS(self):
        self.send_response(204)
        self._add_cors_headers()
        self.end_headers()

    # ── helpers ──
    def _serve_html(self):
        body = self._html_bytes
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-cache")
        self._add_cors_headers()
        self.end_headers()
        self.wfile.write(body)

    def _send_json(self, code, body):
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self._add_cors_headers()
        self.end_headers()
        self.wfile.write(body)

    def _send_text(self, code, body):
        self.send_response(code)
        self.send_header("Content-Type", "text/plain")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _add_cors_headers(self):
        """Allow the browser-side JS to call out to public APIs (npm, PyPI, etc.)."""
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, Authorization")


# ── Server helpers ────────────────────────────────────────────────────────────
def _find_free_port(preferred: int) -> int:
    """Return *preferred* if it is free, otherwise find the next available port."""
    import socket
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            s.bind(("127.0.0.1", preferred))
            return preferred
        except OSError:
            s.bind(("127.0.0.1", 0))
            return s.getsockname()[1]


def _decode_html() -> bytes:
    """Decode the embedded base64 HTML once and return as UTF-8 bytes."""
    raw = base64.b64decode(_HTML_B64)
    # Verify it looks like HTML (sanity check)
    if b"<html" not in raw[:200].lower():
        raise RuntimeError(
            "Embedded HTML payload appears corrupt — please regenerate OSLS_App.py."
        )
    return raw


def _open_browser(url: str, delay: float = 0.8):
    """Open the browser after a short delay (gives the server time to start)."""
    def _go():
        time.sleep(delay)
        webbrowser.open(url)
    t = threading.Thread(target=_go, daemon=True)
    t.start()


def _print_banner(url: str, port: int):
    sep = "─" * 56
    print(f"\n  {sep}")
    print(f"  🔍  Open Source License Scanner  ·  v24")
    print(f"  {sep}")
    print(f"  ▶  Running at  {url}")
    print(f"  ▶  Press  Ctrl+C  to stop the server")
    print(f"  {sep}\n")


# ── Entry point ───────────────────────────────────────────────────────────────
def main():
    parser = argparse.ArgumentParser(
        description="OSLS v24 — self-contained local launcher",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "--port", "-p",
        type=int,
        default=8420,
        help="TCP port to listen on (default: 8420)",
    )
    parser.add_argument(
        "--no-browser",
        action="store_true",
        help="Do not open the browser automatically",
    )
    args = parser.parse_args()

    # Decode the embedded HTML
    try:
        html_bytes = _decode_html()
    except Exception as exc:
        print(f"\n[OSLS] ERROR: Could not decode embedded HTML — {exc}\n")
        sys.exit(1)

    # Inject decoded bytes into the handler class
    OSLSHandler._html_bytes = html_bytes

    # Find a free port
    port = _find_free_port(args.port)
    if port != args.port:
        print(f"[OSLS] Port {args.port} is in use — using {port} instead.")

    url = f"http://localhost:{port}"

    # Configure & start the server
    server = HTTPServer(("127.0.0.1", port), OSLSHandler)
    server.allow_reuse_address = True

    # Graceful shutdown on Ctrl+C
    def _shutdown(sig, frame):
        print("\n[OSLS] Shutting down…")
        threading.Thread(target=server.shutdown, daemon=True).start()
        sys.exit(0)

    signal.signal(signal.SIGINT, _shutdown)
    if hasattr(signal, "SIGTERM"):
        signal.signal(signal.SIGTERM, _shutdown)

    _print_banner(url, port)

    if not args.no_browser:
        _open_browser(url)

    server.serve_forever()


# ── Embedded HTML payload ─────────────────────────────────────────────────────
# This block is written by the build step below; do not edit manually.
# fmt: off

if __name__ == "__main__":
    # If _HTML_B64 is still None it means this script is being run before
    # the HTML was embedded.  Detect and embed automatically if the HTML
    # file sits next to this .py file.
    if _HTML_B64 is None:
        _candidates = [
            os.path.join(os.path.dirname(os.path.abspath(__file__)),
                         "OpenSourceLicenseScanner_v24.html"),
        ]
        _found = None
        for _c in _candidates:
            if os.path.isfile(_c):
                _found = _c
                break

        if _found:
            with open(_found, "rb") as _fh:
                _HTML_B64 = base64.b64encode(_fh.read()).decode("ascii")
            print(f"[OSLS] Loaded HTML from: {_found}")
        else:
            print(
                "[OSLS] ERROR: Could not find OpenSourceLicenseScanner_v24.html\n"
                "       Place it in the same folder as OSLS_App.py and re-run."
            )
            sys.exit(1)

    main()
